import { Component, inject, OnInit, signal, computed } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { debounceTime, distinctUntilChanged } from 'rxjs';
import { Tramite } from '../../../../../models/tramite';
import { TramiteEscritoLibreService } from '../../../../../controllers/tramite.escrito.libre.service';
import { TramiteService } from '../../../../../controllers/tramite.service';

@Component({
  selector: 'app-paso-1-escrito-libre',
  standalone: true,
  imports: [FormsModule, CommonModule, ReactiveFormsModule],
  templateUrl: './paso-1-escrito-libre.html',
  styleUrl: './paso-1-escrito-libre.css',
  host: {
    '[class.has-changes]': 'hasChanges()'
  }
})
export class Paso1EscritoLibre implements OnInit {
  tramite ?: Tramite

  private tramiteService = inject(TramiteService);
  private tramiteEscritoLibreService = inject(TramiteEscritoLibreService);
  private fb = inject(FormBuilder);

  escritoForm: FormGroup;

  loading = signal(false);
  saving = signal(false);
  hasChanges = signal(false);
  saveMessage = signal('');
  lastSaved = signal<Date | null>(null);

  readonly AUTOSAVE_DELAY = 3000;

  characterCount = computed(() => {
    const content = this.escritoForm.get('contenido')?.value || '';
    return content.length;
  });

  wordCount = computed(() => {
    const content = this.escritoForm.get('contenido')?.value || '';
    return content.trim() ? content.trim().split(/\s+/).length : 0;
  });



  saveStatusText = computed(() => {
    if (this.saving()) return 'Guardando...';
    if (this.lastSaved()) return `Guardado a las ${this.formatTime(this.lastSaved()!)}`;
    if (this.hasChanges()) return 'Tienes cambios sin guardar';
    return '';
  });

  constructor() {
    this.escritoForm = this.fb.group({
      contenido: ['', [Validators.required]]
    });

    this.setupAutosave();
  }

  async ngOnInit() {
    await this.loadTramite()
    this.loadExistingEscrito();
  }

  async loadTramite(){
    this.tramite = await this.tramiteService.getCurrentTramite();
  }

  private setupAutosave() {
    this.escritoForm.get('contenido')?.valueChanges.pipe(
      debounceTime(this.AUTOSAVE_DELAY),
      distinctUntilChanged()
    ).subscribe(() => {
      this.autoSave();
    });
  }

  private async loadExistingEscrito() {
    if (!this.tramite?.id) {
      return;
    }

    this.loading.set(true);

    const existing = await this.tramiteEscritoLibreService.first({
      tramite_id: this.tramite!.id
    });

    if (existing) {
      this.escritoForm.patchValue({ contenido: existing.contenido });
      const savedDate = existing.updated_at ?? existing.created_at ?? new Date().toISOString();
      this.lastSaved.set(new Date(savedDate));
    }
    this.loading.set(false);
  }

  async autoSave() {
    if (!this.escritoForm.valid || this.saving()) return;

    const content = this.escritoForm.get('contenido')?.value;
    if (!content || content.trim().length === 0) return;

    await this.saveEscrito(false);
  }

  async saveManually() {
    if (this.escritoForm.invalid) {
      this.escritoForm.markAllAsTouched();
      this.saveMessage.set('Por favor, completa el campo del escrito.');
      setTimeout(() => this.saveMessage.set(''), 5000);
      return;
    }

    await this.saveEscrito(true);
  }

  private async saveEscrito(showMessage = true) {
    if (!this.tramite?.id) return;

    this.saving.set(true);

    const content = this.escritoForm.get('contenido')?.value;

    const existing = await this.tramiteEscritoLibreService.first({
      tramite_id: this.tramite!.id
    });

    if (existing) {
      await this.tramiteEscritoLibreService.update(existing.id, { contenido: content }, showMessage);
    } else {
      await this.tramiteEscritoLibreService.new({
        tramite_id: this.tramite!.id,
        contenido: content
      });
    }

    this.lastSaved.set(new Date());
    this.hasChanges.set(false);

    if (showMessage) {
      this.saveMessage.set('Escrito guardado correctamente');
      setTimeout(() => this.saveMessage.set(''), 3000);
    }

    this.saving.set(false);
  }

  onContentChange() {
    this.hasChanges.set(true);
  }

  formatTime(date: Date): string {
    return date.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' });
  }

  get contenido() {
    return this.escritoForm.get('contenido');
  }
}
